import FeatureSectionV1 from "./components/feature-section-v1"

export default function Page() {
  return <FeatureSectionV1 />
}

.fsv1-card-front,
.fsv1-card-back {
  transition:
    transform 0.32s cubic-bezier(0.87, 0, 0.13, 1),
    opacity 0.32s cubic-bezier(0.87, 0, 0.13, 1);
  will-change: transform, opacity;
}

.fsv1-card-back {
  transform: translateY(-100%);
  opacity: 0;
}

.fsv1-card:hover .fsv1-card-front {
  transform: translateY(100%);
  opacity: 0;
}

.fsv1-card:hover .fsv1-card-back {
  transform: translateY(0);
  opacity: 1;
}

.fsv1-card::after {
  content: "";
  position: absolute;
  bottom: 0.35rem;
  right: 0.35rem;
  width: 0.55rem;
  height: 0.55rem;
  border-right: 1px dashed color-mix(in oklab, var(--foreground) 25%, transparent);
  border-bottom: 1px dashed color-mix(in oklab, var(--foreground) 25%, transparent);
  pointer-events: none;
  z-index: 10;
}

@media (prefers-reduced-motion: reduce) {
  .fsv1-card-front,
  .fsv1-card-back {
    transition: none;
  }
}
